import { useCallback } from 'react';

import { getCanvasColor } from '../functions/canvas-color.js';
import { useCanvas } from '../hooks/useCanvas.js';

interface CircleCanvasProps {
  x: number;
  y: number;
  r: number;
  color: string;
  strokeColor?: string;
  strokeWidth?: number;
  opacity?: number;
}

export const CircleCanvas = (props: CircleCanvasProps) => {
  const {
    x,
    y,
    r,
    color,
    strokeColor = color,
    strokeWidth = 0,
    opacity = 1,
  } = props;

  const draw = useCallback(
    (ctx: CanvasRenderingContext2D) => {
      ctx.beginPath();
      ctx.save();
      ctx.arc(x, y, r, 0, 2 * Math.PI);
      ctx.globalAlpha = opacity;
      ctx.fillStyle = getCanvasColor(color);
      ctx.fill();

      ctx.restore();
      // reset opacity and filters, so it doesn't affect other shapes
      ctx.globalAlpha = 1;
      ctx.lineWidth = strokeWidth;
      ctx.strokeStyle = getCanvasColor(strokeColor);

      ctx.stroke();
      ctx.restore();
      ctx.closePath();

      return false;
    },
    [x, y, r, color, strokeColor, strokeWidth],
  );

  useCanvas('circle', draw);

  return null;
};
